import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.contentsafety import ContentSafetyClient
from azure.ai.contentsafety.models import (
    TextCategoryFilterType,
    TextCategoryFilterSettings,
    TextFilterMode,
    BreakStyle,
)
from typing import List, Dict


def redact_unsafe_spans(text: str) -> str:
    endpoint = os.getenv("AZURE_CONTENT_SAFETY_ENDPOINT")
    key = os.getenv("AZURE_CONTENT_SAFETY_KEY")
    client = ContentSafetyClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )
    category_filters = {
        TextCategoryFilterType.HATE: TextCategoryFilterSettings(
            filter_mode=TextFilterMode.REDRACT
        ),
        TextCategoryFilterType.SEXUAL: TextCategoryFilterSettings(
            filter_mode=TextFilterMode.REDRACT
        ),
        TextCategoryFilterType.VIOLENCE: TextCategoryFilterSettings(
            filter_mode=TextFilterMode.REDRACT
        ),
        TextCategoryFilterType.SELF_HARM: TextCategoryFilterSettings(
            filter_mode=TextFilterMode.REDRACT
        ),
    }
    poller = client.filter_text(
        text=text,
        category_filters=category_filters,
        break_style=BreakStyle.PAD_WITH_MEANINGFUL_WORD,
    )
    result = poller.result()
    return result.filtered_text


def flag_unsafe_spans(text: str) -> List[Dict[str, str]]:
    endpoint = os.getenv("AZURE_CONTENT_SAFETY_ENDPOINT")
    key = os.getenv("AZURE_CONTENT_SAFETY_KEY")
    client = ContentSafetyClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )
    category_filters = {
        TextCategoryFilterType.HATE: TextCategoryFilterSettings(
            filter_mode=TextFilterMode.REDRACT
        ),
        TextCategoryFilterType.SEXUAL: TextCategoryFilterSettings(
            filter_mode=TextFilterMode.REDRACT
        ),
        TextCategoryFilterType.VIOLENCE: TextCategoryFilterSettings(
            filter_mode=TextFilterMode.REDRACT
        ),
        TextCategoryFilterType.SELF_HARM: TextCategoryFilterSettings(
            filter_mode=TextFilterMode.REDRACT
        ),
    }
    poller = client.filter_text(
        text=text,
        category_filters=category_filters,
        break_style=BreakStyle.NONE,
    )
    result = poller.result()
    spans = []
    for location in result.filter_metadata.text_category_locations:
        spans.append(
            {
                "category": location.category.value,
                "start_index": location.location.index,
                "length": location.location.length,
            }
        )
    return spans
